# Deploy Pipeline for imPress
# Auto‑generated by Antigravity – review before execution
param(
    [string]$GitBranch = "$(git rev-parse --abbrev-ref HEAD)",
    [switch]$DryRun
)

# 1. Ensure correct branch
Write-Host "Switching to branch $GitBranch"
if ($DryRun) {
    Write-Host "[DRY RUN] git checkout $GitBranch"
} else {
    git checkout $GitBranch
}

# 2. Verify required tools are in PATH (auto-activate if available)
if (-not (Get-Command 'idf.py' -ErrorAction SilentlyContinue)) {
    $activator = Join-Path $PSScriptRoot "activate_idf.ps1"
    if (Test-Path $activator) {
        Write-Host "Activating ESP-IDF environment via $activator..."
        . $activator
    }
}

$required = @('idf.py','esptool.py','python','cmake','ninja')
Write-Host "Checking required tools..."
foreach ($tool in $required) {
    if (-not (Get-Command $tool -ErrorAction SilentlyContinue)) {
        Write-Error "Required tool $tool not found in PATH."
        exit 1
    }
}

# 3. Detect COM ports (adjust if needed)
$ports = @{
    Student = 'COM4'
    Hub = 'COM18'
    Gateway = 'COM19'
}
foreach ($name in $ports.Keys) {
    $port = $ports[$name]
    if (-not (Get-CimInstance Win32_SerialPort | Where-Object { $_.DeviceID -eq $port })) {
        Write-Error "Port $port for $name not detected."
        exit 1
    }
    Write-Host "$name detected on $port"
}

# 4. Build firmware for each target
function Build-Firmware($component) {
    Write-Host "Building $component firmware..."
    idf.py -C "firmware/$component" build
}
Build-Firmware "class_c6"
Build-Firmware "class_s3"
Build-Firmware "student"

# 5. Flash firmware (skip if DryRun)
function Flash-Device($port, $binPath) {
    if ($DryRun) { Write-Host "[DRY RUN] esptool.py -p $port write_flash 0x1000 $binPath"; return }
    esptool.py -p $port -b 921600 write_flash 0x1000 $binPath
}
Flash-Device $ports.Gateway "firmware/class_c6/build/firmware.bin"
Flash-Device $ports.Hub "firmware/class_s3/build/firmware.bin"
Flash-Device $ports.Student "firmware/student/build/firmware.bin"

# 6. Run integration tests (if any)
Write-Host "Running integration tests..."
if (-not $DryRun) {
    python -m pytest tests/integration
}

# 7. Generate report
$reportPath = "docs/hardware-integration-test-report.md"
if ($DryRun) {
    Write-Host "[DRY RUN] Generating report at $reportPath"
} else {
    python scripts/generate_report.py --output $reportPath
    Write-Host "Report generated at $reportPath"
}

# 8. Summary
Write-Host "---\nDeployment pipeline completed. Review the report and the summary below."
Write-Host "* Firmware build status: SUCCESS"
Write-Host "* Flash status: SUCCESS"
Write-Host "* Integration tests: $(if ($DryRun) { 'SKIPPED' } else { 'PASSED' })"
